sketches.source:
setcpm(40/4)

// Bowls struck one at a time, each left to ring out
bowls: note("<c4 ~ g4 ~ eb4 ~ ~ bb3>").s("sine").fm(1.2).fmh(2.76)
  .decay(8).sustain(0).release(8)
  .pan(sine.slow(8)).space("hall").gain(.24)

// A large bowl, slightly out of tune with the others, so they beat gently
greatbowl: note("<c3 ~ ~ ~ ~ ~ ~ ~>").s("sine").fm(.8).fmh(2.41)
  .decay(10).sustain(0).release(10).room(.8).size(.95).gain(.28)

// The hum underneath, with a faint overtone whistle
hum: note("c2").slow(8).s("hum").overtone(6).gain(.16)

// Soft air in the room
air: s("pink").slow(8).lpf(600).gain(.03)

setcpm(50/4)

// The choir breathes slow, open chords
choir: note("<[c3,g3,c4] [c3,g3,d4] [c3,f3,c4] [c3,g3,c4]>").slow(2)
  .s("choir").syl("<oh ah oo oh>")
  .attack(2).release(3).space("church").gain(.32)

// A reed drone that never moves
drone: note("[c2,g2]").slow(8).s("sawtooth").timbre("reed")
  .lpf(500).attack(3).sustain(1).release(4).gain(.14)

// Distant bells
bells: note("<g4 ~ ~ ~ c5 ~ ~ ~>").s("sine").fm(3).fmh(2.41)
  .decay(4).sustain(0).release(4).space("church").gain(.14)

// Birds outside the walls
birds: s("bird").slow(4).azimuth(-60).distance(8).occlude(.4).gain(.16)

setcpm(40/4)

// A guiding hum that circles and slowly rises across sixteen cycles
guide: note("<a3 c4 e4 g4>").slow(4).s("hum")
  .azimuth(saw.range(-180, 180).slow(4))
  .elevation(saw.range(0, 60).slow(16))
  .distance(2).posglide(.5).attack(2).release(3).gain(.3)

// A still drone at the centre
drone: note("[a1,e2]").slow(8).s("sine").attack(4).sustain(1).release(6).gain(.22)

// Soft air all around
air: s("pink").slow(8).lpf(500).gain(.03)

// A small bell at the start of each round
bell: note("<a4 ~ ~ ~ ~ ~ ~ ~>").s("sine").fm(2).fmh(2.76)
  .decay(5).sustain(0).release(5).space("hall").gain(.12)

setcpm(40/4)

// A slow binaural drone: each ear is detuned by 1 Hz, so a 2 Hz beat forms
drone: note("<a1 a1 f1 g1>").slow(4).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.32)

// A pad that barely moves
pad: note("<[a2,e3,b3] [f2,c3,g3]>").slow(8)
  .s("sawtooth").unison(4).detune(.3)
  .attack(6).release(8).lpf(600).room(.8).size(.95).gain(.1)

// Warm brown noise, like a distant waterfall
bed: s("brown").slow(8).lpf(400).gain(.08)

setcpm(44/4)

// A 6 Hz binaural beat: keep the volume low
drone: note("<d2 d2 bb1 c2>").slow(4).s("sine").binaural(6)
  .attack(4).sustain(1).release(6).gain(.3)

// Slow, breathing choir chords
choir: note("<[d3,a3,f4] [bb2,f3,d4] [g2,d3,bb3] [a2,e3,c#4]>").slow(2)
  .s("choir").syl("<oo ah oh oo>")
  .attack(3).release(4).space("hall").gain(.24)

// A stream nearby
stream: s("stream").slow(4).distance(4).gain(.18)
